   299  static void
   300  fu_uswid_firmware_class_init(FuUswidFirmwareClass *klass)
   301  {
   302          FuFirmwareClass *firmware_class = FU_FIRMWARE_CLASS(klass);
   303          firmware_class->validate = fu_uswid_firmware_validate;
   304          firmware_class->parse = fu_uswid_firmware_parse;
   305          firmware_class->write = fu_uswid_firmware_write;
   306          firmware_class->build = fu_uswid_firmware_build;
   307          firmware_class->export = fu_uswid_firmware_export;
   308  }
